      &lt;ActionType&gt;ShowToast&lt;/ActionType&gt;
      &lt;Description&gt;DatadeInceput &amp;lt; DatadeSfarsit&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;Heading&quot;:&quot;Atentionare!&quot;,&quot;Message&quot;:&quot;&amp;lt;p&amp;gt;Atentie! Data de Sfarsit: [p_DatadeSfarsit] este anterioara Datei de Inceput: [p_DatadeInceput] !&amp;lt;/p&amp;gt;&quot;,&quot;Icon&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;warning&quot;},&quot;BgColor&quot;:&quot;#2d88a6&quot;,&quot;Transition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;slide&quot;},&quot;AllowToastClose&quot;:true,&quot;CallBackJsCode&quot;:null,&quot;HideTime&quot;:&quot;10000&quot;,&quot;Stack&quot;:&quot;1&quot;,&quot;ToastPosition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;mid-center&quot;},&quot;TextAlignment&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;left&quot;},&quot;ShowLoader&quot;:true,&quot;LoaderColor&quot;:&quot;#FFFF00&quot;}&lt;/ActionData&gt;
      &lt;Condition&gt;[p_DatadeInceput] &amp;gt; [p_DatadeSfarsit]&lt;/Condition&gt;
