    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;1508&lt;/ModuleId&gt;
      &lt;FieldName&gt;Add&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;4&lt;/OrderIndex&gt;
      &lt;ActionType&gt;ExecuteActions&lt;/ActionType&gt;
      &lt;Description&gt;Interval disponibil in CO si CM&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;ActionList&quot;:[{&quot;Id&quot;:8295,&quot;GlobalId&quot;:&quot;00000000-0000-0000-0000-000000000000&quot;,&quot;Description&quot;:&quot;Interval CO disponibil (in CO si CM)&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:11280,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Condition&quot;:&quot;&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:true,&quot;Entry&quot;:&quot;&quot;},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;SqlQuery&quot;:&quot;SELECT \n    IIF(\n        EXISTS (\n            SELECT 1\n            FROM app.ConcediudeOdihna co\n            WHERE co.Marca = @marca\n              AND co.DatadeInceput &amp;lt; @end\n              AND co.DatadeSfarsit &amp;gt; @start\n        )\n        OR EXISTS (\n            SELECT 1\n            FROM app.ConcediuMedical cm\n            WHERE cm.Marca = @marca\n              AND cm.DatadeInceput &amp;lt; @end\n              AND cm.DatadeSfarsit &amp;gt; @start\n        ),\n        0, -- suprapunere cu CO sau CM\n        1  -- liber\n    ) AS disponibil;\n&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[p_DatadeInceput]&quot;,&quot;name&quot;:&quot;start&quot;},{&quot;value&quot;:&quot;[p_DatadeSfarsit]&quot;,&quot;name&quot;:&quot;end&quot;},{&quot;value&quot;:&quot;[p_Marca]&quot;,&quot;name&quot;:&quot;marca&quot;}],&quot;OutputTokenName&quot;:&quot;interval&quot;,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false,&quot;UseTransactions&quot;:true},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true},{&quot;Id&quot;:8296,&quot;GlobalId&quot;:&quot;00000000-0000-0000-0000-000000000000&quot;,&quot;Description&quot;:&quot;Verificare perioada CO disponibila&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:11280,&quot;ActionType&quot;:&quot;ShowToast&quot;,&quot;Condition&quot;:&quot;[interval:disponibil] == 0&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:1,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Heading&quot;:&quot;Atentionare!&quot;,&quot;Message&quot;:&quot;&amp;lt;p&amp;gt;Exista CO/CM in intervalul selectat!&amp;lt;/p&amp;gt;&quot;,&quot;Icon&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;warning&quot;},&quot;BgColor&quot;:&quot;#2d88a6&quot;,&quot;Transition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;slide&quot;},&quot;AllowToastClose&quot;:true,&quot;CallBackJsCode&quot;:null,&quot;HideTime&quot;:&quot;10000&quot;,&quot;Stack&quot;:&quot;1&quot;,&quot;ToastPosition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;mid-center&quot;},&quot;TextAlignment&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;left&quot;},&quot;ShowLoader&quot;:true,&quot;LoaderColor&quot;:&quot;#FFFF00&quot;},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}],&quot;OnError&quot;:[]}&lt;/ActionData&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;1508&lt;/ModuleId&gt;
      &lt;FieldName&gt;Add&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;5&lt;/OrderIndex&gt;
      &lt;ActionType&gt;ExecuteActions&lt;/ActionType&gt;
      &lt;Description&gt;Zile CO in luna curenta &amp;lt; Zile Lucratoare&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;ActionList&quot;:[{&quot;Id&quot;:8298,&quot;GlobalId&quot;:&quot;00000000-0000-0000-0000-000000000000&quot;,&quot;Description&quot;:&quot;Calcul Zile_CO_Luna&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:11283,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Condition&quot;:&quot;[interval:disponibil] == 1&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;SqlQuery&quot;:&quot;select sum(NrZileCO1+NrZileCO2+NrZileCO3) as Zile_CO_Luna from app.ConcediudeOdihna\nwhere \n((year(Interval1DatadeInceput)=@Anul and month(Interval1DatadeInceput)=@Luna)\nor \n(year(Interval2DatadeInceput)=@Anul and month(Interval2DatadeInceput)=@Luna)\nor (year(Interval3DatadeInceput)=@Anul and month(Interval3DatadeInceput)=@Luna))\nand CodSucursala=@CodSucursala \nand Marca=@Marca&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;},{&quot;value&quot;:&quot;[GET:p_Marca]&quot;,&quot;name&quot;:&quot;Marca&quot;}],&quot;OutputTokenName&quot;:&quot;Token&quot;,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false,&quot;UseTransactions&quot;:true},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true},{&quot;Id&quot;:8299,&quot;GlobalId&quot;:&quot;00000000-0000-0000-0000-000000000000&quot;,&quot;Description&quot;:&quot;Verificare Zile_CO_Luna &amp;lt;= ZileLucratoare&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:11283,&quot;ActionType&quot;:&quot;ShowToast&quot;,&quot;Condition&quot;:&quot;[Token:Zile_CO_Luna] != &#39;&#39; &amp;amp;&amp;amp; [Token:Zile_CO_Luna] &amp;gt;  [Initializari:ZileLucratoare_old(Anul=[GetOrSession:YearV], Luna=[GetOrSession:MonthV])]&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:1,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Heading&quot;:&quot;Atentionare!&quot;,&quot;Message&quot;:&quot;&amp;lt;p&amp;gt;Nu se poate salva! Zilele de concediu depășesc zilele lucrătoare ale lunii.\nZile lucrătoare: [Initializari:ZileLucratoare_old(Anul=[GetOrSession:YearV], Luna=[GetOrSession:MonthV])]\nZile deja &#238;nregistrate: [Token:Zile_CO_Luna]&amp;amp;nbsp;&amp;lt;/p&amp;gt;&quot;,&quot;Icon&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;warning&quot;},&quot;BgColor&quot;:&quot;#2d88a6&quot;,&quot;Transition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;slide&quot;},&quot;AllowToastClose&quot;:true,&quot;CallBackJsCode&quot;:null,&quot;HideTime&quot;:&quot;10000&quot;,&quot;Stack&quot;:&quot;1&quot;,&quot;ToastPosition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;mid-center&quot;},&quot;TextAlignment&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;left&quot;},&quot;ShowLoader&quot;:true,&quot;LoaderColor&quot;:&quot;#FFFF00&quot;},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}],&quot;OnError&quot;:[]}&lt;/ActionData&gt;
      &lt;Condition /&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;1508&lt;/ModuleId&gt;
      &lt;FieldName&gt;Add&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;6&lt;/OrderIndex&gt;
      &lt;ActionType&gt;ExecuteActions&lt;/ActionType&gt;
      &lt;Description&gt;Verificare Numar ZileCO  la care are dreptul in functie de AnReferinta si Zile CO ramase pentru AnReferinta&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;ActionList&quot;:[{&quot;Id&quot;:8301,&quot;GlobalId&quot;:&quot;00000000-0000-0000-0000-000000000000&quot;,&quot;Description&quot;:&quot;Numar ZileCO la care are dreptul in functie de AnReferinta&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:11286,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Condition&quot;:&quot;&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;SqlQuery&quot;:&quot;SELECT \n    CASE \n        WHEN (d.ZileCODrept - ISNULL(f.ZileCOFolosite, 0)) &amp;gt;= 0 \n        THEN (d.ZileCODrept - ISNULL(f.ZileCOFolosite, 0))\n        ELSE 0\n    END AS ZileCORamase\nFROM \n(\n    SELECT \n        CASE \n            WHEN @AnReferintaCO = @Anul THEN\n                (SELECT ZileCO \n                 FROM app.Salariat \n                 WHERE Marca = @Marca \n                   AND Anul = @Anul \n                   AND Luna = @Luna)\n            ELSE\n                (SELECT ZileCO \n                 FROM app.Salariat \n                 WHERE Marca = @Marca \n                   AND Anul = @AnReferintaCO \n                   AND Luna = 12)\n        END AS ZileCODrept\n) d\nCROSS JOIN\n(\n    SELECT ISNULL(SUM(ZileCO),0) AS ZileCOFolosite\n    FROM app.ConcediudeOdihna\n    WHERE Marca = @Marca\n      AND AnReferintaCO = @AnReferintaCO\n) f\n&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[p_Marca]&quot;,&quot;name&quot;:&quot;Marca&quot;},{&quot;value&quot;:&quot;[p_AnReferintaCO]&quot;,&quot;name&quot;:&quot;AnReferintaCO&quot;},{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;OutputTokenName&quot;:&quot;Token&quot;,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false,&quot;UseTransactions&quot;:true},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true},{&quot;Id&quot;:8302,&quot;GlobalId&quot;:&quot;00000000-0000-0000-0000-000000000000&quot;,&quot;Description&quot;:&quot;Verificare Zile CO ramase pentru AnReferinta&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:11286,&quot;ActionType&quot;:&quot;ShowToast&quot;,&quot;Condition&quot;:&quot;[p_ZileCO] &amp;gt; [Token:ZileCORamase]&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:1,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Heading&quot;:&quot;Atentionare!&quot;,&quot;Message&quot;:&quot;&amp;lt;p&amp;gt;Ati introdus mai multe zile de CO dec&#226;t cele disponibile!&amp;lt;/p&amp;gt;&quot;,&quot;Icon&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;warning&quot;},&quot;BgColor&quot;:&quot;#2d88a6&quot;,&quot;Transition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;plain&quot;},&quot;AllowToastClose&quot;:true,&quot;CallBackJsCode&quot;:null,&quot;HideTime&quot;:&quot;10000&quot;,&quot;Stack&quot;:&quot;1&quot;,&quot;ToastPosition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;mid-center&quot;},&quot;TextAlignment&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;left&quot;},&quot;ShowLoader&quot;:true,&quot;LoaderColor&quot;:&quot;#FFFF00&quot;},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}],&quot;OnError&quot;:[]}&lt;/ActionData&gt;
      &lt;Condition&gt;[Token:ZileCORamase] &amp;lt; [ZileCODrept]&lt;/Condition&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
